import axios from "axios";

const getRipeProbes = async()=>{

    const FetchProbesFromServer = async()=>{
        const response = await axios.get('https://ripe-13prsouz.uc.gateway.dev/probes');
        mapProbes(response.data);
    }

    const mapProbes=(probeData)=>{
        const mappedProbes = ([]);
        for (let i=0; i < probeData.length; i++){
            mappedProbes[i] = {geocode: [mappedProbes.lat, mappedProbes.lng],
                popUp: mappedProbes.id
            }
            
        }
    }

    FetchProbesFromServer();

    return FetchProbesFromServer();
    
}

export default getRipeProbes;
